create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, nome text, avatar text, role text not null default 'user' check (role in ('user','admin')), created_at timestamptz not null default now());
create table if not exists public.albums (id uuid primary key default gen_random_uuid(), nome text not null, descricao text, ano int, capa_url text, total_stickers int not null default 0, ativo boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.stickers (id uuid primary key default gen_random_uuid(), album_id uuid not null references public.albums(id) on delete cascade, codigo text not null, nome text not null, selecao text, tipo text, foto_url text, ordem int, created_at timestamptz not null default now(), unique(album_id,codigo));
create table if not exists public.collections (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, album_id uuid not null references public.albums(id) on delete cascade, created_at timestamptz not null default now(), unique(user_id,album_id));
create table if not exists public.user_stickers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, sticker_id uuid not null references public.stickers(id) on delete cascade, quantidade int not null default 1 check (quantidade >= 0), updated_at timestamptz not null default now(), unique(user_id,sticker_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,nome,avatar) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),new.raw_user_meta_data->>'avatar_url'); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.albums enable row level security; alter table public.stickers enable row level security; alter table public.collections enable row level security; alter table public.user_stickers enable row level security;
create policy "profiles own" on public.profiles for select using (auth.uid()=id); create policy "albums public read" on public.albums for select using (ativo=true or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin')); create policy "stickers public read" on public.stickers for select using (true); create policy "collections own" on public.collections for all using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy "user stickers own" on public.user_stickers for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create policy "admin albums write" on public.albums for all using (public.is_admin()) with check (public.is_admin()); create policy "admin stickers write" on public.stickers for all using (public.is_admin()) with check (public.is_admin());
